class Solution(object):
    def maxSlidingWindow(self, nums, k):
        if not nums or not k:
            return []

        # Initialize deque to store indices of max numbers
        deque = collections.deque()

        result = []

        for i, num in enumerate(nums):
            # Remove elements from the end that are smaller than the current number
            while deque and nums[deque[-1]] < num:
                deque.pop()

            # Add the current index to the deque
            deque.append(i)

            # If the first element is out of the current window, remove it
            if i >= k - 1:
                result.append(nums[deque[0]])
                # If the first element is removed, make sure to update the deque if necessary
                if deque[0] == i - k + 1:
                    deque.popleft()

        return result
